            side = R * 2
            ox, oy = (config.SCREEN_WIDTH - self.grid.columns * side) / 2, (config.SCREEN_HEIGHT - self.grid.rows * side) / 2
            return int((y - oy) // side), int((x - ox) // side)
        else:
            w, h = math.sqrt(3) * R, 1.5 * R
            ox, oy = (config.SCREEN_WIDTH - (self.grid.columns + 0.5) * w) / 2, (config.SCREEN_HEIGHT - ((self.grid.rows - 1) * h + 2 * R)) / 2
            r = int((y - oy - R) / h + 0.5)
